function configureBottomDegreeMarkers(){if(!initialized||!structureGroup)return;let group=structureGroup.getObjectByName('bottom-degree-markers');if(!group){group=new THREE.Group();group.name='bottom-degree-markers';group.userData.kind='direction';group.add(bottomDegreeSprite('180° / 北',0,-10.8),bottomDegreeSprite('0° / 南',0,10.8),bottomDegreeSprite('90° / 东',-10.8,0),bottomDegreeSprite('270° / 西',10.8,0));group.visible=false;structureGroup.add(group)}const bottom=document.querySelector('#viewBottomBtn'),iso=document.querySelector('#viewIsoBtn'),top=document.querySelector('#viewTopBtn'),front=document.querySelector('#viewFrontBtn'),overlay=document.querySelector('#bottomOrientation');if(!bottom||!iso||!top||!front||bottom.dataset.degreeMarkers)return;bottom.dataset.degreeMarkers='true';const hide=()=>{group.visible=false;if(overlay)overlay.hidden=true};[iso,top,front].forEach(button=>{const original=button.onclick;button.onclick=event=>{hide();original?.call(button,event)}});const originalBottom=bottom.onclick;bottom.onclick=event=>{originalBottom?.call(bottom,event);if(overlay)overlay.hidden=true;group.visible=true}}
function maintainBottomDegreeMarkers(){configureBottomDegreeMarkers();requestAnimationFrame(maintainBottomDegreeMarkers)}
requestAnimationFrame(maintainBottomDegreeMarkers);
function keepBottomDegreeMarkersInFrame(){const group=structureGroup?.getObjectByName('bottom-degree-markers');if(group?.children.length===4){group.children[0].position.set(0,-.7,8.7);group.children[1].position.set(0,-.7,-8.7);group.children[2].position.set(10.2,-.7,0);group.children[3].position.set(-10.2,-.7,0);group.children[0].material.rotation=Math.PI;group.children[1].material.rotation=Math.PI}requestAnimationFrame(keepBottomDegreeMarkersInFrame)}
