function keepBottomDegreeTextUpright(){const group=structureGroup?.getObjectByName('bottom-degree-markers');if(group?.children.length===4){[group.children[0],group.children[1]].forEach(sprite=>{if(!sprite.userData.textureFlipped){const source=sprite.material.map.image,canvas=document.createElement('canvas');canvas.width=source.width;canvas.height=source.height;const context=canvas.getContext('2d');context.translate(canvas.width,canvas.height);context.rotate(Math.PI);context.drawImage(source,0,0);sprite.material.map.dispose();sprite.material.map=new THREE.CanvasTexture(canvas);sprite.material.needsUpdate=true;sprite.userData.textureFlipped=true}sprite.material.rotation=0})}requestAnimationFrame(keepBottomDegreeTextUpright)}
