function configureReadableBottomDegrees(){if(!initialized)return;const orientation=document.querySelector('#bottomOrientation'),bottom=document.querySelector('#viewBottomBtn'),iso=document.querySelector('#viewIsoBtn'),top=document.querySelector('#viewTopBtn'),front=document.querySelector('#viewFrontBtn'),group=structureGroup?.getObjectByName('bottom-degree-markers');if(!orientation||!bottom||!iso||!top||!front||bottom.dataset.readableDegrees)return;bottom.dataset.readableDegrees='true';orientation.innerHTML='<b class="north">180° / 北</b><b class="south">0° / 南</b><b class="west">270° / 西</b><b class="east">90° / 东</b><span>仰视方向</span>';const hide=()=>{orientation.hidden=true;if(group)group.visible=false};[iso,top,front].forEach(button=>{const original=button.onclick;button.onclick=event=>{hide();original?.call(button,event)}});const originalBottom=bottom.onclick;bottom.onclick=event=>{originalBottom?.call(bottom,event);if(group)group.visible=false;orientation.hidden=false}}
