let centeredPointSource=null,centeredPointLength=-1;
function centerOverallDefectClusters(){
  if(!root||centeredPointSource===points&&centeredPointLength===points.length)return;
  centeredPointSource=points;centeredPointLength=points.length;
  root.children.filter(object=>object.userData.kind==='defect-count').forEach(object=>root.remove(object));
  const clusters=new Map();
  points.forEach(mesh=>{mesh.visible=true;const key=`${mesh.userData.position}|${mesh.position.y.toFixed(3)}`;if(!clusters.has(key))clusters.set(key,[]);clusters.get(key).push(mesh)});
  clusters.forEach(items=>{const main=items[0],position=coord(main.userData.position);main.position.set(position.x,main.position.y,position.z);main.userData.records=items.map(item=>item.userData.record);items.slice(1).forEach(item=>{item.visible=false});if(items.length>1){const count=sectionSprite(`×${items.length}`,main.material.color.getHex(),.48,.25);count.position.set(position.x+.22,main.position.y+.18,position.z);count.userData.kind='defect-count';root.add(count)}});
}
function maintainCenteredDefects(){centerOverallDefectClusters();requestAnimationFrame(maintainCenteredDefects)}
requestAnimationFrame(maintainCenteredDefects);

function addOffsetDimension(group,info,color){
  if(Math.abs(info.offset)<.001)return;
  const x=-.58,tick=.12,geometry=new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(x,info.base,0),new THREE.Vector3(x,info.y,0),
    new THREE.Vector3(x-tick,info.base,0),new THREE.Vector3(x+tick,info.base,0),
    new THREE.Vector3(x-tick,info.y,0),new THREE.Vector3(x+tick,info.y,0)
  ]),line=new THREE.LineSegments(geometry,new THREE.LineBasicMaterial({color,transparent:true,opacity:.9,depthTest:false}));
  line.renderOrder=49;line.userData.kind='offset-dimension';group.add(line);
}

buildSingleTubeSection=function(position){
  if(focusSectionGroup)modelGroup.remove(focusSectionGroup);
  const group=new THREE.Group();group.name='single-tube-section';
  const tubeId=(parity==='odd'?ODD:EVEN).indexOf(position)+1;
  const records=all.filter(row=>row.position===position&&((row.unit_id%2===1)===(parity==='odd'))&&(!unitSelect.value||row.unit_id===+unitSelect.value)&&(!outageSelect.value||row.outage===outageSelect.value)&&isDefectRecord(row));
  const tubeMaterial=new THREE.MeshStandardMaterial({color:parity==='odd'?0x4b91a8:0x62a38c,metalness:.18,roughness:.42});
  const tube=new THREE.Mesh(new THREE.CylinderGeometry(.22,.22,8.87,20),tubeMaterial);tube.position.y=4.715;group.add(tube);
  const boundaries=[8.35,7.5,6.3,5.2,3.6,1.9,.28];
  for(let index=0;index<6;index+=1){const top=boundaries[index],bottom=boundaries[index+1],color=COLORS[`P${index+1}`],sleeve=new THREE.Mesh(new THREE.CylinderGeometry(.38,.38,top-bottom-.04,32,1,true),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.24,side:THREE.DoubleSide,depthWrite:false}));sleeve.position.y=(top+bottom)/2;group.add(sleeve);const ring=new THREE.Mesh(new THREE.TorusGeometry(.58,.035,8,40),new THREE.MeshBasicMaterial({color}));ring.rotation.x=Math.PI/2;ring.position.y=top;group.add(ring);const connector=new THREE.Line(new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(.58,top,0),new THREE.Vector3(.92,top,0)]),new THREE.LineBasicMaterial({color,transparent:true,opacity:.8,depthTest:false}));connector.renderOrder=49;group.add(connector);const label=sectionSprite(`P${index+1}`,color,1.05,.38);label.position.set(1.4,top,0);group.add(label)}
  const clusters=new Map();
  records.forEach(record=>{const info=locationInfo(record.location),key=`${info.zone}|${info.offset}|${info.y.toFixed(3)}`;if(!clusters.has(key))clusters.set(key,{info,records:[]});clusters.get(key).records.push(record)});
  const labels=[];
  [...clusters.values()].sort((a,b)=>b.info.y-a.info.y).forEach(cluster=>{const strongest=cluster.records.reduce((highest,item)=>(item.percent||0)>(highest.percent||0)?item:highest,cluster.records[0]),depth=strongest.percent||0,color=depth>=riskLimits.high?0xd9534f:depth>=riskLimits.low?0xe5a442:0x64b58a,point=new THREE.Mesh(new THREE.SphereGeometry(.068,14,10),new THREE.MeshStandardMaterial({color,emissive:color,emissiveIntensity:.5}));point.position.set(0,cluster.info.y,0);point.userData={kind:'defect',position,record:strongest,records:cluster.records};group.add(point);addOffsetDimension(group,cluster.info,color);if(cluster.records.length>1){const count=sectionSprite(`×${cluster.records.length}`,color,.48,.25);count.position.set(.3,cluster.info.y+.16,0);count.userData.kind='defect-count';group.add(count)}cluster.records.forEach(record=>labels.push({record,info:cluster.info,color}))});
  labels.sort((a,b)=>b.info.y-a.info.y);let previousLabelY=Infinity;
  labels.forEach(item=>{const labelY=Math.min(item.info.y,previousLabelY-.39);previousLabelY=labelY;const leader=new THREE.Line(new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(0,item.info.y,0),new THREE.Vector3(-.54,labelY,0)]),new THREE.LineBasicMaterial({color:item.color,transparent:true,opacity:.72,depthTest:false}));leader.renderOrder=49;group.add(leader);const sign=item.info.offset>=0?'+':'',text=`${item.info.zone}${sign}${item.info.offset}mm · ${item.record.indication||'-'} · ${item.record.percent??'-'}%`,label=sectionSprite(text,item.color,2.65,.34);label.position.set(-1.86,labelY,0);group.add(label)});
  const title=sectionSprite(`${tubeId}号管 · ${position}`,0x8eb7b0,2.35,.52,true);title.position.set(0,9.62,0);group.add(title);
  focusSectionGroup=group;modelGroup.add(group);return records;
};
